from __future__ import annotations
import csv,collections
from pathlib import Path
from .common import *

def report(cfg):
 out=Path(cfg['artifact_dir']);summary=load_json(out/'evaluation/summary.json');results=read_jsonl(out/'evaluation/results.jsonl');metrics=read_jsonl(out/'evaluation/retrieval_metrics.jsonl');errors=read_jsonl(out/'evaluation/error_analysis.jsonl');error_byid={r['id']:r for r in errors};manifest=load_json(out/'corpus/manifest.json');graph=load_json(out/'graph_validation.json');extraction=load_json(out/'extraction/status.json');freeze=load_json(out/'run_freeze.json');reports=out/'reports';reports.mkdir(parents=True,exist_ok=True)
 n=summary['total'];pct=lambda x:f'{100*x:.1f}%';counts=collections.Counter(e['primary_category'] for e in errors)
 def esc(s):return str(s).replace('|','\\|').replace('\n',' ')
 def avg(key,subset=None):
  vals=[r[key] for r in (subset or metrics) if r[key] is not None];return sum(vals)/len(vals) if vals else 0
 lines=['# Korean Finance GraphRAG — V1 Evaluation Report','',f'Generated: {now()}','',f'**Accuracy: {summary["correct"]}/{n} = {pct(summary["accuracy"])}.** Every benchmark item received a binary local-LLM judgment. Incorrect: {summary["incorrect"]}.',f'Wilson 95% interval: {pct(summary["wilson_95_interval"][0])}–{pct(summary["wilson_95_interval"][1])}. This interval reflects finite sample size, not uncertainty in the LLM judge.','', '## Scope and completion','',f'- Corpus: {manifest["products"]} products, {manifest["source_documents"]} source occurrences, {manifest["unique_documents"]} unique document versions, {manifest["units"]} source units, {manifest["chunks"]} chunks.',f'- Persisted graph: {graph["nodes"]} nodes, {graph["edges"]} edges, {graph["facts"]} semantic facts.',f'- Successful extraction: {extraction["completed_chunks"]}/{extraction["requested_chunks"]} chunks; selected source-unit coverage {pct(extraction["unit_coverage"])}. Unit coverage measures selection, not extraction correctness.',f'- Fact provenance coverage: {pct(graph["fact_provenance_coverage"])}. Graph integrity validation: {graph["valid"]}. Rejected unsupported entity mentions: {extraction["rejected_entities"]}.',f'- Model: `{cfg["model_id"]}`, revision `{cfg["model_revision"]}`, local MLX 4-bit inference. Extraction, answer generation, evaluation, and diagnosis run outside Codex in the local model.', '- No remote LLM API was called. No additional model training was performed.','', '## Ontology and architecture','', 'The English ontology is in `docs/ontology.md`. Source, Document, Chunk, and Product nodes preserve structure. Rule, Condition, Requirement, Benefit, and Restriction nodes hold source-bound assertions; Organization and Concept nodes support a small semantic expansion. A fact’s statement is the source text selected by the extraction LLM, preserving original Korean values and qualifications.','', 'The pipeline uses deterministic Markdown paragraphs and HTML-table rows, expanding rowspan/colspan values while recording the raw table span. Unique documents are chunked once. Source occurrences retain their product and file-path links. Raw prompts, generations, retries, source units, chunks, and graph exports are retained.','', 'SQLite stores the property graph transactionally with indexed edges. Retrieval combines Korean character n-gram BM25, explicit product matching, product–source–document scope traversal, fact–entity expansion, SUPPORTED_BY evidence traversal, and NEXT_CHUNK context expansion. The final answer model receives typed facts and source chunks within a fixed character budget. This is a hybrid graph-and-text RAG baseline, not a graph-only system.','', '## Benchmark isolation and methodology','', '- Before QA, the benchmark is projected to exactly `id` and `question`. Product/source hints, answers, rationales, aliases, and benchmark evidence are excluded from retrieval and generation.', '- The graph, prompts, configuration, and implementation hashes are frozen before benchmark QA. Answer hashes are frozen before gold answers are opened by evaluation.', '- Evaluation receives the question, reference answer, allowed aliases, rationale, and generated answer. It returns only correct/incorrect plus an explanation; no partial credit is used.', '- Source evidence and benchmark metadata enter only post-generation evaluation and error analysis. No V2 changes or benchmark-directed retries were performed after scoring.', '- The evaluator uses the same local model weights as the answer generator, with a separate request and grading prompt. This is a limitation: shared-model bias and evaluator mistakes are possible. These are model-judged results, not a human-certified accuracy estimate.',f'- Frozen graph SHA-256: `{freeze["graph_sha256"]}`.',f'- Frozen answers SHA-256: `{summary["answers_hash"]}`.','', '## Accuracy by group','']
 for field,groups in summary['by_group'].items():
  lines+=['### '+field,'','| Group | Correct | Total | Accuracy |','|---|---:|---:|---:|']
  for group,v in groups.items():lines.append(f'| {esc(group)} | {v["correct"]} | {v["total"]} | {pct(v["accuracy"])} |')
  lines.append('')
 lines+=['## Retrieval diagnostics','',f'- Mean annotated-document recall: {pct(avg("gold_document_recall"))}.',f'- All annotated source documents retrieved: {sum(m["all_gold_documents_retrieved"] is True for m in metrics)}/{n}.',f'- Mean reference-evidence character-bigram coverage in final context: {pct(avg("evidence_bigram_coverage_in_context"))}.',f'- Mean reference-evidence character-bigram coverage in retrieved source chunks: {pct(avg("evidence_bigram_coverage_in_source_chunks"))}.',f'- Mean reference-evidence character-bigram coverage in retrieved graph nodes (full stored statements): {pct(avg("evidence_bigram_coverage_in_retrieved_facts"))}.',f'- Mean reference-evidence character-bigram coverage in all facts of annotated documents: {pct(avg("evidence_bigram_coverage_in_all_gold_document_facts"))}.',f'- Unresolved source annotations: {sum(len(m["unresolved_gold_sources"]) for m in metrics)}.','', 'Document recall treats content-identical file copies as the same document version. Long graph statements are explicitly marked as shortened previews in the answer context; full statements remain stored, and `truncated_fact_ids` records this distinction. Bigram coverage is a lexical diagnostic proxy, not semantic evidence recall, a proof of entailment, or a grading signal. Alternative valid sources may support a correct answer even when an annotated source is absent.','', '## Error categories','', '| Primary category | Count |','|---|---:|']
 for category in ('ontology_design','information_extraction','graph_construction','retrieval','source_document_retrieval','answer_generation','evaluation_issue','unknown'):lines.append(f'| {category} | {counts[category]} |')
 lines+=['', 'Root causes are local-LLM diagnoses informed by graph/source inspection and retrieval logs. They are hypotheses rather than controlled causal ablations. Passing graph integrity checks establishes referential correctness, not semantic completeness. An `evaluation_issue` diagnosis does not change the original score.','', '## Representative successes','']
 successes=[];seen=set()
 for r in results:
  if r['correct'] and r['reasoning_type'] not in seen:successes.append(r);seen.add(r['reasoning_type'])
 for r in successes[:5]:lines += [f'### {r["id"]}','',r['question'],'',f'Prediction: {r["answer"]}','',f'Judge: {r["reason"]}','']
 lines+=['## Representative failures',''];failures=[];seen=set()
 for r in results:
  if not r['correct']:
   category=error_byid.get(r['id'],{}).get('primary_category','unknown')
   if category not in seen:failures.append(r);seen.add(category)
 for r in failures[:8]:
  error=error_byid.get(r['id'],{});lines+=[f'### {r["id"]}: {error.get("primary_category","unknown")}','',r['question'],'',f'Reference: {r["ground_truth_answer"]}','',f'Prediction: {r["answer"]}','',f'Judge: {r["reason"]}','',f'Diagnosis ({error.get("confidence","unknown")} confidence): {error.get("reason","")}','']
 proposals={
 'retrieval':'Improve product-name resolution and cross-product coverage using source-derived aliases plus a multilingual semantic retriever or reranker. Compare a fixed V2 against V1 on a held-out set; avoid question-specific product rules.',
 'source_document_retrieval':'Retrieve evidence at source-unit granularity and explicitly follow table footnotes/definitions before spending the context budget. Log evidence lost to the budget and preserve benefit/exception groups.',
 'answer_generation':'Add a constrained calculation step for dates, percentages, caps, and eligibility conjunctions. Require a brief evidence checklist for all requested conditions. Test a stronger local answer model on a fixed comparison set before considering an approved remote API.',
 'information_extraction':'Audit unselected source units, add an extraction completeness pass, and validate semantic fact type against the selected text. Keep exact-source selection but separate unrelated assertions and preserve dependent footnotes.',
 'ontology_design':'Extend the ontology with Quantity, TemporalScope, ConditionGroup, and Exception plus APPLIES_WHEN/EXCEPT_WHEN edges. Specify AND/OR, boundary inclusivity, percentage versus percentage-point units, and product/version scope.',
 'graph_construction':'Add targeted invariant checks for source/product scope and cross-document evidence identity, and inspect the specific faulty traversal before changing storage technology.',
 'evaluation_issue':'Use a second independent local judge and a small human-adjudicated audit; report judge disagreement separately and retain the original V1 judgments.',
 'unknown':'Manually trace a bounded sample from raw source through extraction and retrieval to generation before attributing failure to a specific stage.'}
 lines+=['## Proposed V2 — bounded follow-up','']
 for category,count in counts.most_common():
  if count:lines.append(f'- **{category} ({count} observed failures):** {proposals[category]}')
 lines += ['- Independently of observed categories, retain a graph-only versus hybrid versus text-only retrieval ablation to measure the graph’s contribution. V1 has no such ablation, so its score alone cannot establish a gain over text RAG.', '- Freeze a separate V2 artifact directory and evaluation plan. Implement one bounded set of improvements, then run one comparison. No V2 optimization has been performed automatically.','', '## Complete per-question results','', '| ID | Correct | Type | Error category | Question |','|---|---|---|---|---|']
 for r in results:lines.append(f'| [{r["id"]}](questions/{r["id"]}.md) | {"correct" if r["correct"] else "incorrect"} | {esc(r["qa_type"])} | {error_byid.get(r["id"],{}).get("primary_category","")} | {esc(r["question"])} |')
 lines += ['', '## Reproduction and artifacts','', 'See the project README for environment setup and commands. `artifacts/v1/graph.sqlite` is sufficient for graph-backed source retrieval; the local model is additionally required to generate new answers. `graph_export/nodes.jsonl` and `edges.jsonl` are portable graph exports. `evaluation/results.jsonl`, `error_analysis.jsonl`, and `retrieval_metrics.jsonl` preserve every judgment and diagnostic. The `llm` directory contains content-addressed prompts and raw model outputs.','']
 (reports/'evaluation_report.md').write_text('\n'.join(lines),encoding='utf-8')
 with (reports/'per_question.csv').open('w',encoding='utf-8-sig',newline='') as f:
  fields=['id','correct','qa_type','difficulty','reasoning_type','question','ground_truth_answer','answer','reason','primary_category'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
  for r in results:w.writerow({**{k:r[k] for k in fields if k in r},'primary_category':error_byid.get(r['id'],{}).get('primary_category','')})
 for r in results:
  trace=load_json(out/'retrieval'/f'{r["id"]}.json');error=error_byid.get(r['id']);body=f'# {r["id"]} — {"correct" if r["correct"] else "incorrect"}\n\n## Question\n\n{r["question"]}\n\n## Model answer\n\n{r["answer"]}\n\nCitations: '+', '.join(r['citations'])+f'\n\n## Reference answer\n\n{r["ground_truth_answer"]}\n\n## Reference rationale\n\n{r["ground_truth_rationale"]}\n\n## Binary evaluation\n\n{r["reason"]}\n'
  if error:body+='\n## Error diagnosis\n\n'+json.dumps(error,ensure_ascii=False,indent=2)+'\n'
  body+='\n## Citation mapping\n\n```json\n'+json.dumps(trace['citation_map'],ensure_ascii=False,indent=2)+'\n```\n\n## Retrieved context\n\n'+trace['context']+'\n';p=reports/'questions'/f'{r["id"]}.md';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body,encoding='utf-8')
 print('REPORT '+str(reports/'evaluation_report.md'),flush=True)
 return reports/'evaluation_report.md'
